code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # The divider rows/columns occur every five cells; the final panel may be four cells wide.
    step = 5
    bands, cols = (h + 1) // step, (w + 1) // step
    dividers = {v for v in grid[step-1] if v != 0}
    divider = next(iter(dividers), 5)
    out = [row[:] for row in grid]
    colors = []
    for br in range(bands):
        vals = [grid[br*step+r][c] for r in (1,2) for c in (1,2)]
        colors.append(next((v for v in vals if v not in (0, divider)), 0))
    # The design is the panel whose colored-cell count exceeds that of the 2x2 color keys.
    pattern = set()
    for br in range(bands):
        for bc in range(cols):
            pts = {(r,c) for r in range(4) for c in range(4)
                   if grid[br*step+r][bc*step+c] not in (0, divider)}
            if len(pts) > 4:
                pattern = pts
                break
        if pattern:
            break
    for br, color in enumerate(colors):
        for bc in range(cols):
            for r,c in pattern:
                out[br*step+r][bc*step+c] = color
    return out
'''
